css:
.uv-browser-loader {
  width: 320px;
  border-radius: 18px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.04);
  box-shadow: 0 28px 80px rgba(0, 0, 0, 0.55);
  overflow: hidden;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  position: relative;
}

.uv-topbar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.06),
    rgba(255, 255, 255, 0.03)
  );
}

.uv-dot {
  width: 10px;
  height: 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.16);
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.25);
}
.uv-url {
  margin-left: auto;
  width: 150px;
  height: 12px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.uv-body {
  padding: 16px 14px 14px;
  position: relative;
}

.uv-row {
  height: 12px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.07);
  margin: 10px 0;
  overflow: hidden;
  position: relative;
}
.uv-h1 {
  height: 14px;
  width: 72%;
}
.uv-short {
  width: 56%;
}

/* skeleton shimmer */
.uv-row::before {
  content: "";
  position: absolute;
  inset: -40% -60%;
  background: linear-gradient(
    110deg,
    transparent 0%,
    rgba(255, 255, 255, 0.1) 22%,
    rgba(255, 255, 255, 0.2) 30%,
    transparent 44%
  );
  transform: translateX(-60%);
  animation: uvShimmer 1.15s cubic-bezier(0.2, 0.8, 0.2, 1) infinite;
  mix-blend-mode: screen;
}

.uv-trace {
  margin-top: 14px;
  height: 4px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.07);
  overflow: hidden;
  position: relative;
}
.uv-trace::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    rgba(110, 231, 255, 0),
    rgba(110, 231, 255, 0.65),
    rgba(176, 140, 255, 0.55),
    rgba(110, 231, 255, 0)
  );
  transform: translateX(-70%);
  animation: uvTrace 1.05s cubic-bezier(0.2, 0.8, 0.2, 1) infinite;
  filter: saturate(1.1);
}

/* Loading text shine */
.uv-loading {
  margin-top: 14px;
  font:
    600 12px/1 ui-sans-serif,
    system-ui;
  letter-spacing: 0.2px;
  color: rgba(255, 255, 255, 0.72);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  position: relative;
}
.uv-loading span:first-child {
  position: relative;
  background: linear-gradient(
    90deg,
    rgba(255, 255, 255, 0.55),
    rgba(255, 255, 255, 0.95),
    rgba(255, 255, 255, 0.55)
  );
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  background-size: 200% 100%;
  animation: uvTextShine 1.1s ease-in-out infinite;
}
.uv-ell {
  opacity: 0.65;
  animation: uvDots 1s steps(3, end) infinite;
}

@keyframes uvShimmer {
  to {
    transform: translateX(60%);
  }
}
@keyframes uvTrace {
  to {
    transform: translateX(70%);
  }
}
@keyframes uvTextShine {
  0% {
    background-position: 0% 50%;
    opacity: 0.7;
  }
  50% {
    opacity: 1;
  }
  100% {
    background-position: 100% 50%;
    opacity: 0.75;
  }
}
@keyframes uvDots {
  0% {
    opacity: 0.35;
  }
  50% {
    opacity: 1;
  }
  100% {
    opacity: 0.35;
  }
}
